import Capacitor
import UserNotifications

public class PushNotificationsHandler: NSObject, NotificationHandlerProtocol {
    public weak var plugin: CAPPlugin?
    var notificationRequestLookup = [String: JSObject]()

    public func requestPermissions(with completion: ((Bool, Error?) -> Void)? = nil) {
        UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge]) { granted, error in
            completion?(granted, error)
        }
    }

    public func checkPermissions(with completion: ((UNAuthorizationStatus) -> Void)? = nil) {
        UNUserNotificationCenter.current().getNotificationSettings { settings in
            completion?(settings.authorizationStatus)
        }
    }

    public func willPresent(notification: UNNotification) -> UNNotificationPresentationOptions {
        let notificationData = makeNotificationRequestJSObject(notification.request)
        self.plugin?.notifyListeners("pushNotificationReceived", data: notificationData)
        let userInfo = notification.request.content.userInfo
        let rawData: [AnyHashable: Any] = (userInfo["data"] as? [AnyHashable: Any]) ?? userInfo
        let type = (rawData["type"] as? String) ?? (userInfo["type"] as? String) ?? ""
        if type.starts(with: "CALL_") || type.contains("INITIATE") {
            return []
        }
        return [.banner, .badge, .sound]
    }

    public func didReceive(response: UNNotificationResponse) {
        var data = makeNotificationRequestJSObject(response.notification.request)
        data["actionId"] = response.actionIdentifier
        self.plugin?.notifyListeners("pushNotificationActionPerformed", data: data)
    }

    public func makeNotificationRequestJSObject(_ request: UNNotificationRequest) -> JSObject {
        var notification: JSObject = [
            "id": request.identifier,
            "title": request.content.title,
            "body": request.content.body
        ]
        if let badge = request.content.badge {
            notification["badge"] = badge.intValue
        }

        let userInfo = request.content.userInfo
        var customData: JSObject = [:]
        for (key, value) in userInfo {
            if let keyStr = key as? String, keyStr != "aps" {
                if let strVal = value as? String {
                    customData[keyStr] = strVal
                } else if let boolVal = value as? Bool {
                    customData[keyStr] = boolVal
                } else if let numVal = value as? NSNumber {
                    customData[keyStr] = numVal
                } else {
                    customData[keyStr] = "\(value)"
                }
            }
        }
        if let nestedData = userInfo["data"] as? [String: Any] {
            for (k, v) in nestedData {
                if let strVal = v as? String {
                    customData[k] = strVal
                } else if let boolVal = v as? Bool {
                    customData[k] = boolVal
                } else if let numVal = v as? NSNumber {
                    customData[k] = numVal
                } else {
                    customData[k] = "\(v)"
                }
            }
        }
        notification["data"] = customData
        return notification
    }
}
